for (let step = 0; step < MAX_STEPS; step++) {
  const result = await llm.complete(messages, toolSpecs);

  if (result.kind === "final") {
    push({ role: "assistant", content: result.content });
    return;
  }

  const tool = toolRegistry.get(result.toolCall.name);
  const output = await tool.run(result.toolCall.args);
  push({ role: "tool", content: output });
}

function defineTool<T>(spec: {
  name: string;
  description: string;
  schema: z.ZodType<T>;
  run: (args: T) => Promise<string>;
}): Tool {
  return {
    name: spec.name,
    description: spec.description,
    run: (raw: unknown) => spec.run(spec.schema.parse(raw)),
  };
}
